Fixes the issue.

---

@bruvzg regarding adding the tests Calinou mentioned this should do:
https://github.com/godotengine/godot/blob/235a32ad11f40ecba26d6d9ceea8ab245c13adb0/tests/core/string/test_string.h#L876
```cpp
format = "fish %d frog";
args.clear();
args.push_back(INT64_MIN);
output = format.sprintf(args, &error);
REQUIRE(error == false);
CHECK(output == String("fish -9223372036854775808 frog"));

format = "fish %x frog";
args.clear();
args.push_back(INT64_MIN);
output = format.sprintf(args, &error);
REQUIRE(error == false);
CHECK(output == String("fish -8000000000000000 frog"));

format = "fish %X frog";
args.clear();
args.push_back(INT64_MIN);
output = format.sprintf(args, &error);
REQUIRE(error == false);
CHECK(output == String("fish -8000000000000000 frog"));

format = "fish %o frog";
args.clear();
args.push_back(INT64_MIN);
output = format.sprintf(args, &error);
REQUIRE(error == false);
CHECK(output == String("fish -1000000000000000000000 frog"));
```
